class Animal { void sound() { System.out.println("Sound"); } }
class Cat extends Animal { @Override void sound() { System.out.println("Meow"); } }
public class Main { public static void main(String[] args) { Animal pet = new Cat(); pet.sound(); } }

class Shape { int sides() { return 0; } }
class Triangle extends Shape { int sides() { return 3; } }
class Hexagon extends Shape { int sides() { return 6; } }
public class Main { public static void main(String[] args) { Shape[] shapes = {new Triangle(), new Hexagon()}; for (Shape s : shapes) System.out.println(s.sides()); } }

class Worker { String role() { return "Worker"; } }
class Designer extends Worker { String role() { return "Designer"; } }
public class Main { static void printRole(Worker w) { System.out.println(w.role()); } public static void main(String[] args) { printRole(new Designer()); } }

class Device { String name() { return "Device"; } }
class Phone extends Device { String name() { return "Phone"; } }
public class Main { public static void main(String[] args) { Device d = new Phone(); System.out.println(d.name()); } }

class Base { void run() { System.out.println("Base"); } }
class Fast extends Base { @Override void run() { System.out.println("Fast"); } }
public class Main { public static void main(String[] args) { Base b = new Fast(); b.run(); } }
